def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_me, last_opp = history[-1]
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c

    if n >= 97:
        return 'D'

    if opp_d == 0:
        if last_me == 'D':
            return 'D'
        if n >= 20 and n % 10 == 0:
            return 'D'
        return 'C'

    if opp_c == 0:
        return 'D'

    recent = opp[-10:]
    recent_d = recent.count('D')

    if recent_d >= 7:
        return 'D'

    if opp_d > opp_c * 2:
        return 'D'

    if last_opp == 'D':
        if last_me == 'C':
            if opp_c > n * 0.4 and rng.random() < 0.5:
                return 'C'
            return 'D'
        else:
            if opp_c > n * 0.1:
                my_streak = 0
                for a in reversed(me):
                    if a == 'D':
                        my_streak += 1
                    else:
                        break
                opp_streak = 0
                for b in reversed(opp):
                    if b == 'D':
                        opp_streak += 1
                    else:
                        break
                if my_streak >= 3 and opp_streak >= 3:
                    return 'C'
                if opp_c > n * 0.8 and my_streak >= 2 and opp_streak >= 2:
                    if rng.random() < 0.5:
                        return 'C'
            return 'D'
    else:
        if last_me == 'D':
            if opp_c > n * 0.8:
                return 'D'
            return 'C'
        else:
            if recent_d >= 2 and rng.random() < 0.3:
                return 'D'
            return 'C'
